package com.aistock.prediction.analysis;
import com.aistock.prediction.marketuse.*;import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class AnalysisMarketUseForwardingTest {
 @Test void marketEvidenceReceivesExactlyTheOriginalUsageAndScopeIsCleared()throws Exception{var json=new ObjectMapper();var evidence=new AnalysisFactsTest().sample();var seen=new AtomicReference<String>();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var raw=UUID.fromString("11111111-1111-4111-8111-111111111111");var op=UUID.randomUUID().toString();var bundle=UUID.randomUUID().toString();server.createContext("/",e->{seen.set(e.getRequestHeaders().getFirst("X-Market-Use-Bundle"));if(seen.get()!=null){assertEquals(op,e.getRequestHeaders().getFirst("X-Market-Use-Operation"));assertEquals("1",e.getRequestHeaders().getFirst("X-Market-Use-Generation"));assertEquals("STOCK_ANALYSIS",e.getRequestHeaders().getFirst("X-Market-Use-Purpose"));assertEquals("prediction",e.getRequestHeaders().getFirst("X-Market-Use-Owner"));}var body=json.createObjectNode().put("code","OK");body.set("data",evidence);var bytes=json.writeValueAsBytes(body);e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();try{var c=new HttpAnalysisMarketClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",json);var r=new MarketUseClient.Request(op,"1",UUID.randomUUID().toString(),raw.toString());try(var scope=MarketUseContext.open(r,new MarketUseClient.Receipt(bundle,"ACTIVE",List.of(raw.toString())))){c.evidence("SH600030",LocalDate.parse("2026-07-07"),LocalDate.parse("2026-10-07"),raw);assertEquals(bundle,seen.get());}assertTrue(MarketUseContext.headers().isEmpty());c.evidence("SH600030",LocalDate.parse("2026-07-07"),LocalDate.parse("2026-10-07"),raw);assertNull(seen.get());}finally{server.stop(0);}}
}
